  const base = await realpath(root).catch(() => null);
  if (base === null) return err(`cannot resolve index root ${root}`);

  const target = resolve(base, relative);
  if (!contained(base, target)) return err("path escapes the index root");

  const stat = await lstat(target).catch((e: NodeJS.ErrnoException) => e);
  if (stat instanceof Error) {
    if (stat.code === "ENOENT" || stat.code === "ENOTDIR") return { kind: "missing" };
    return err(`cannot read: ${stat.code ?? "unknown error"}`);
  }
  if (stat.isSymbolicLink()) return err("symlinks are not accepted");
  if (!stat.isFile()) return err("not a regular file");
  if (stat.size > MAX_METADATA_BYTES) {
    return err(`larger than ${MAX_METADATA_BYTES} bytes`);
  }

  // Catches a symlinked *parent* directory, which lstat on the leaf cannot see.
  const real = await realpath(target).catch(() => null);
  if (real === null || !contained(base, real)) return err("path escapes the index root");

  return { kind: "text", text: await readFile(target, "utf8") };
