```ts
export async function readIndexFile(
  root: string,
  relative: string,
): Promise<FileRead> {
  const error = (reason: string): FileRead => ({ kind: "error", reason });

  if (relative.includes("\0") || isAbsolute(relative)) {
    return error("path must be relative to the index root");
  }

  const base = await realpath(root).catch(() => null);
  if (base === null) return error(`cannot resolve index root ${root}`);

  const target = resolve(base, relative);
  if (!contained(base, target)) return error("path escapes the index root");

  // Only a genuinely absent path is "missing". Every other errno used to
  // collapse into it, and "missing" now means "an owner deleted this" — so an
  // EACCES or EIO on a file that also exists in the committed tree, which is
  // what an ordinary *modification* looks like, would be authorized as a
  // deletion with its ref, registry host and owner id never read. Neither
  // template can reach that state, so this closes a fail-open on fault rather
  // than a live exploit.
  let stat;
  try {
    stat = await lstat(target);
  } catch (err) {
    const code = (err as NodeJS.ErrnoException).code;
    if (code === "ENOENT" || code === "ENOTDIR") return { kind: "missing" };
    return error(`cannot read: ${code ?? "unknown error"}`);
  }

  if (stat.isSymbolicLink()) return error("symlinks are not accepted");
  if (!stat.isFile()) return error("not a regular file");
  if (stat.size > MAX_METADATA_BYTES) {
    return error(`larger than ${MAX_METADATA_BYTES} bytes`);
  }

  // Catches a symlinked *parent* directory, which lstat on the leaf cannot see.
  const real = await realpath(target).catch(() => null);
  if (real === null || !contained(base, real)) {
    return error("path escapes the index root");
  }

  return { kind: "text", text: await readFile(target, "utf8") };
}
```

- Added a local `error(reason)` helper to remove the repeated `{ kind: "error", reason }` literals.
- Replaced the `lstat(...).catch(...)` + `stat instanceof Error` pattern with a plain `try/catch`, same errno checks.
- Kept both rationale comments and every check/order/error message unchanged.

