```ts
export function usePackageRoot(
  ns: MaybeRefOrGetter<string>,
  pkg: MaybeRefOrGetter<string>,
  wireBase: MaybeRefOrGetter<string> = '',
) {
  const root = ref<PackageRoot | null>(null)
  const loading = ref(true)
  const error = ref<string | null>(null)
  const notFound = ref(false)

  // Monotonic request token: guards every state write below against a
  // slow, now-superseded response landing after a newer navigation already
  // fired its own fetch.
  let requestToken = 0

  onMounted(() => {
    watch(
      // `wireBase` is watched too: two packages from different sources have
      // different mount prefixes.
      () => [toValue(ns), toValue(pkg), toValue(wireBase)] as const,
      async ([nsVal, pkgVal, baseVal]) => {
        const token = ++requestToken
        const stale = () => token !== requestToken
        loading.value = true
        error.value = null
        notFound.value = false
        try {
          const base = wirePrefix(baseVal)
          // Alias first, canonical second: the canonical `/p/<ns>/<pkg>.json`
          // path is blocked by EasyList/EasyPrivacy for some package names
          // (see `sources/mirror.ts`'s `_root.json` alias). The canonical
          // path stays as fallback for trees mirrored by an older build.
          const urls = [
            `${base}/p/${nsVal}/${pkgVal}/_root.json`,
            `${base}/p/${nsVal}/${pkgVal}.json`,
          ]
          let resp: Response | undefined
          for (const url of urls) {
            resp = await fetch(url)
            if (stale()) return
            if (resp.status !== 404) break
          }
          if (!resp || resp.status === 404) {
            notFound.value = true
            root.value = null
            return
          }
          if (!resp.ok) throw new Error(`HTTP ${resp.status}`)
          const data = await resp.json()
          if (stale()) return
          root.value = data
        } catch (e) {
          if (stale()) return
          error.value = e instanceof Error ? e.message : 'Failed to load package'
          root.value = null
        } finally {
          if (!stale()) loading.value = false
        }
      },
      { immediate: true },
    )
  })

  return { root, loading, error, notFound }
}
```

- Collapsed the alias→canonical two-fetch sequence into a loop over a `urls` array, removing the duplicated fetch/status-check blocks.
- Introduced a `stale()` closure to replace the five repeated `token !== requestToken` checks.
- Kept the token check *before* assigning `root.value = data` (not after), preserving the original stale-response guard exactly.
- Trimmed the long prose comments to the essential rationale (token guard, alias-fetch reason), dropping the illustrative example and duplicate detail.

```ts
export function usePackageRoot(
  ns: MaybeRefOrGetter<string>,
  pkg: MaybeRefOrGetter<string>,
  wireBase: MaybeRefOrGetter<string> = '',
) {
  const root = ref<PackageRoot | null>(null)
  const loading = ref(true)
  const error = ref<string | null>(null)
  const notFound = ref(false)

  // Monotonic request token: guards every state write below against a
  // slow, now-superseded response landing after a newer navigation already
  // fired its own fetch.
  let requestToken = 0

  // Alias first, canonical second. `/p/<ns>/<pkg>.json` — the wire root's
  // own URL — is blocked by EasyList/EasyPrivacy's unanchored `/<word>.js`
  // rules on some package names; `_root.json` (written by `sources/mirror.ts`
  // beside every root) sidesteps that. The canonical path stays as fallback
  // for a tree mirrored by an older build of this package, which has no alias.
  async function fetchRoot(base: string, nsVal: string, pkgVal: string, isCurrent: () => boolean) {
    let resp = await fetch(`${base}/p/${nsVal}/${pkgVal}/_root.json`)
    if (!isCurrent()) return null
    if (resp.status === 404) resp = await fetch(`${base}/p/${nsVal}/${pkgVal}.json`)
    return isCurrent() ? resp : null
  }

  onMounted(() => {
    watch(
      // `wireBase` is watched alongside ns/pkg: the client router reuses this
      // component instance across a nav, and two packages from different
      // sources have different mount prefixes.
      () => [toValue(ns), toValue(pkg), toValue(wireBase)] as const,
      async ([nsVal, pkgVal, baseVal]) => {
        const token = ++requestToken
        const isCurrent = () => token === requestToken
        loading.value = true
        error.value = null
        notFound.value = false
        try {
          const resp = await fetchRoot(wirePrefix(baseVal), nsVal, pkgVal, isCurrent)
          if (!resp) return
          if (resp.status === 404) {
            notFound.value = true
            root.value = null
            return
          }
          if (!resp.ok) throw new Error(`HTTP ${resp.status}`)
          const data = await resp.json()
          if (isCurrent()) root.value = data
        } catch (e) {
          if (isCurrent()) {
            error.value = e instanceof Error ? e.message : 'Failed to load package'
            root.value = null
          }
        } finally {
          if (isCurrent()) loading.value = false
        }
      },
      { immediate: true },
    )
  })

  return { root, loading, error, notFound }
}
```

- Extracted the alias→canonical fetch (with its two token checks) into a nested `fetchRoot` helper.
- Replaced repeated `token !== requestToken` checks with a single `isCurrent()` closure, reused by both the helper and the watch callback.
- Collapsed the intermediate `const base = wirePrefix(baseVal)` into the `fetchRoot` call site.
- Trimmed the explanatory comments to their essential rationale, keeping the EasyList/EasyPrivacy and multi-source `wireBase` notes.
- All state transitions, fetch order, 404/error/finally semantics, and the token-guard points are unchanged.
